import type { JournalSnapshot, Observation, Photo, Plant, Recognition } from '../types/domain'
import type { RecognitionProvider } from './recognition'
import { demoOwner, initialSnapshot, species } from './fixtures'

let sequence = 0
const sessionPrefix = `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`

// Session-only demo IDs. Production IDs must be generated by the trusted backend.
export function createLocalId(kind: string): string {
  sequence += 1
  return `${kind}-${sessionPrefix}-${sequence}`
}

export class MockJournal {
  private snapshot: JournalSnapshot
  private readonly listeners = new Set<() => void>()
  private readonly createdForRecognition = new Map<string, string>()
  private generation = 0

  constructor(
    private readonly ownerId = demoOwner,
    initial: JournalSnapshot = initialSnapshot(),
  ) {
    this.snapshot = {
      plants: initial.plants.filter((item) => item.ownerId === ownerId),
      observations: initial.observations.filter((item) => item.ownerId === ownerId),
      recognitions: initial.recognitions.filter((item) => item.ownerId === ownerId),
    }
  }

  getSnapshot = (): JournalSnapshot => this.snapshot
  subscribe = (listener: () => void): (() => void) => {
    this.listeners.add(listener)
    return () => { this.listeners.delete(listener) }
  }

  private publish(next: JournalSnapshot) {
    this.snapshot = next
    this.listeners.forEach((listener) => listener())
  }

  private recognition(id: string): Recognition {
    const record = this.snapshot.recognitions.find((item) => item.id === id && item.ownerId === this.ownerId)
    if (!record) throw new Error('找不到本次会话的识别记录，请回首页重新选择照片。')
    return record
  }

  private plant(id: string): Plant {
    const record = this.snapshot.plants.find((item) => item.id === id && item.ownerId === this.ownerId)
    if (!record) throw new Error('找不到本次会话的植物档案，请回首页查看。')
    return record
  }

  private updateRecognition(record: Recognition) {
    this.publish({
      ...this.snapshot,
      recognitions: this.snapshot.recognitions.map((item) => item.id === record.id ? record : item),
    })
  }

  startRecognition(photo: Photo, provider: RecognitionProvider): string {
    if (!provider.isDemo) throw new Error('样板仅允许演示服务，真实服务尚未接入。')
    const record: Recognition = {
      id: createLocalId('recognition'),
      ownerId: this.ownerId,
      photo,
      status: 'running',
      rawResult: null,
      confirmedSpeciesId: null,
      failure: null,
      createdAt: new Date().toISOString(),
    }
    this.publish({ ...this.snapshot, recognitions: [record, ...this.snapshot.recognitions] })
    void this.runRecognition(record, provider)
    return record.id
  }

  private async runRecognition(record: Recognition, provider: RecognitionProvider) {
    const generation = this.generation
    try {
      const rawResult = await provider.recognize(record.photo)
      if (generation !== this.generation) return
      if (!rawResult.isDemo) throw new Error('样板不接受真实识别结果。')
      this.updateRecognition({
        ...record,
        rawResult,
        status: rawResult.candidates.length ? 'succeeded' : 'uncertain',
      })
    } catch (error) {
      if (generation !== this.generation) return
      this.updateRecognition({
        ...record,
        status: 'failed',
        failure: error instanceof Error ? error.message : '演示任务失败，请重试。',
      })
    }
  }

  retryRecognition(id: string, provider: RecognitionProvider) {
    const record = this.recognition(id)
    if (!provider.isDemo) throw new Error('尚未接入真实服务。')
    if (record.status !== 'failed') return
    const next: Recognition = { ...record, status: 'running', failure: null }
    this.updateRecognition(next)
    void this.runRecognition(next, provider)
  }

  confirmSpecies(id: string, speciesId: string | null) {
    const record = this.recognition(id)
    if (record.status === 'running') throw new Error('请等待演示结果。')
    if (speciesId && !species.some((item) => item.id === speciesId)) throw new Error('物种不在演示列表中。')
    // The provider's original candidates remain unchanged.
    this.updateRecognition({ ...record, confirmedSpeciesId: speciesId })
  }

  createPlant(recognitionId: string, input: { nickname: string; location: string; story: string }): Plant {
    const record = this.recognition(recognitionId)
    const existing = this.createdForRecognition.get(recognitionId)
    if (existing) return this.plant(existing)
    if (record.status === 'running') throw new Error('请等待演示任务结束。')
    const nickname = input.nickname.trim()
    if (!nickname || nickname.length > 40) throw new Error('请填写 1–40 字昵称。')
    if (input.location.length > 80 || input.story.length > 500) throw new Error('地点最多 80 字，故事最多 500 字。')
    const plant: Plant = {
      id: createLocalId('plant'),
      ownerId: this.ownerId,
      nickname,
      speciesId: record.confirmedSpeciesId,
      locationDescription: input.location.trim(),
      coordinates: null,
      story: input.story.trim(),
      cover: record.photo,
      createdAt: new Date().toISOString(),
    }
    const observation = this.newObservation(plant.id, record.photo, '第一次记住这一株。', recognitionId)
    this.createdForRecognition.set(recognitionId, plant.id)
    this.publish({
      ...this.snapshot,
      plants: [plant, ...this.snapshot.plants],
      observations: [observation, ...this.snapshot.observations],
    })
    return plant
  }

  private newObservation(plantId: string, photo: Photo, note: string, recognitionId: string | null): Observation {
    return {
      id: createLocalId('observation'),
      plantId,
      ownerId: this.ownerId,
      photo,
      note: note.trim(),
      recognitionId,
      observedAt: new Date().toISOString(),
    }
  }

  appendObservation(plantId: string, photo: Photo, note: string): Observation {
    this.plant(plantId)
    if (note.length > 500) throw new Error('观察笔记最多 500 字。')
    const observation = this.newObservation(plantId, photo, note, null)
    this.publish({ ...this.snapshot, observations: [observation, ...this.snapshot.observations] })
    return observation
  }

  linkRecognition(plantId: string, recognitionId: string): Observation {
    this.plant(plantId)
    const record = this.recognition(recognitionId)
    if (record.status === 'running') throw new Error('请等待演示任务结束。')
    const existing = this.snapshot.observations.find((item) => item.plantId === plantId && item.recognitionId === recognitionId)
    if (existing) return existing
    const observation = this.newObservation(plantId, record.photo, '由我确认，记录的是同一株植物。', recognitionId)
    this.publish({ ...this.snapshot, observations: [observation, ...this.snapshot.observations] })
    return observation
  }

  clear() {
    this.generation += 1
    this.createdForRecognition.clear()
    this.publish({ plants: [], observations: [], recognitions: [] })
  }
}
